import{_ as o,c as d,o as a,a5 as c}from"./chunks/framework.DuCYAsAJ.js";const p=JSON.parse('{"title":"Facebook News Feed 系统设计","description":"","frontmatter":{"title":"Facebook News Feed 系统设计","date":"2026-04-20T00:00:00.000Z","order":5},"headers":[],"relativePath":"posts/SystemDesign/fbnewsfeed.md","filePath":"posts/SystemDesign/fbnewsfeed.md","lastUpdated":1779463578000}'),r={name:"posts/SystemDesign/fbnewsfeed.md"};function t(l,e,i,s,h,n){return a(),d("div",null,[...e[0]||(e[0]=[c('<h2 id="facebook-news-feed-系统设计" tabindex="-1">Facebook News Feed 系统设计 <a class="header-anchor" href="#facebook-news-feed-系统设计" aria-label="Permalink to &quot;Facebook News Feed 系统设计&quot;">​</a></h2><p>本文讨论的是 Facebook News Feed 一类的时间线产品，系统要把用户关注的人发布的内容，按时间倒序组织成一条可持续刷新的 Feed，并支持不断向下翻页。它的难点不在于“如何存一条帖子”，而在于 fan-out，一个用户可能关注很多人，一个创作者也可能拥有海量粉丝。于是，系统很容易在两条链路上失控：读路径上，用户打开首页时需要聚合过多数据，形成 fan-out on read；写路径上，用户发帖时需要把帖子扩散给过多粉丝，形成 fan-out on write，这也是这种系统最核心的设计主题</p><h3 id="问题定义与边界" tabindex="-1">问题定义与边界 <a class="header-anchor" href="#问题定义与边界" aria-label="Permalink to &quot;问题定义与边界&quot;">​</a></h3><h4 id="功能需求" tabindex="-1">功能需求 <a class="header-anchor" href="#功能需求" aria-label="Permalink to &quot;功能需求&quot;">​</a></h4><p>用户能够发帖；用户能够关注其他用户；用户能够看到自己关注的人发布的内容；Feed 按时间倒序展示，并支持分页</p><h4 id="非功能需求" tabindex="-1">非功能需求 <a class="header-anchor" href="#非功能需求" aria-label="Permalink to &quot;非功能需求&quot;">​</a></h4><p>高可用：优先可用性，允许最终一致；低延迟：发帖和刷 Feed 尽量收敛在 <code>500ms</code> 以内；大规模：支持约 <code>2B</code> 用户；高扩展：用户可以关注很多人，也可能被很多人关注</p><h4 id="一致性假设" tabindex="-1">一致性假设 <a class="header-anchor" href="#一致性假设" aria-label="Permalink to &quot;一致性假设&quot;">​</a></h4><p>可以接受最多约 <code>1</code> 分钟的帖子延迟进入 Feed；Feed 顺序以“时间倒序”为主，不展开推荐排序</p><h3 id="核心实体、接口与数据模型" tabindex="-1">核心实体、接口与数据模型 <a class="header-anchor" href="#核心实体、接口与数据模型" aria-label="Permalink to &quot;核心实体、接口与数据模型&quot;">​</a></h3><h4 id="核心实体" tabindex="-1">核心实体 <a class="header-anchor" href="#核心实体" aria-label="Permalink to &quot;核心实体&quot;">​</a></h4><p><code>User</code>：系统中的用户；<code>Follow</code>：一条单向关注关系；<code>Post</code>：用户发布的内容；<code>PrecomputedFeed</code>：为用户预先计算好的 Feed 索引</p><p>这里默认采用单向 <code>follow</code> 模型，而不是早期 Facebook 更偏双向的 <code>friend</code> 模型。这样设计，能更直接暴露 fan-out 的问题，也更接近微博 / 关注流产品的形态</p><h4 id="初始-api" tabindex="-1">初始 API <a class="header-anchor" href="#初始-api" aria-label="Permalink to &quot;初始 API&quot;">​</a></h4><ul><li>发帖：<code>POST /posts</code></li><li>关注：<code>PUT /users/{id}/follow</code></li><li>获取 Feed：<code>GET /feed?pageSize={size}&amp;cursor={timestamp}</code></li></ul><p>其中 <code>cursor</code> 可以直接使用“当前页最老一条帖子的时间戳”，用来表示用户已经看到哪里了。下一页只需要返回比它更旧的帖子</p><h4 id="基础数据模型" tabindex="-1">基础数据模型 <a class="header-anchor" href="#基础数据模型" aria-label="Permalink to &quot;基础数据模型&quot;">​</a></h4><p><code>Post</code> 表可以按 <code>postId</code> 主键存储，并额外建立一个按作者查询的索引：主键 <code>postId</code>，GSI <code>creatorId + createdAt</code>。这样系统就能快速查出“某个用户发过哪些帖子”，并天然带有时间顺序。<code>Follow</code> 表的基本形式可以是：主键 <code>userFollowing + userFollowed</code>，反向 GSI <code>userFollowed + userFollowing</code>。这样可以高效支持三类查询：我是否关注了某人、我关注了谁、谁关注了我</p><h3 id="核心架构设计" tabindex="-1">核心架构设计 <a class="header-anchor" href="#核心架构设计" aria-label="Permalink to &quot;核心架构设计&quot;">​</a></h3><h4 id="一、用户能够发帖" tabindex="-1">一、用户能够发帖 <a class="header-anchor" href="#一、用户能够发帖" aria-label="Permalink to &quot;一、用户能够发帖&quot;">​</a></h4><p>最简单的链路，是客户端把发帖请求打到 API Gateway / Load Balancer 后面的 <code>Post Service</code>，服务将帖子写入存储。由于帖子天然是海量、简单、按 Key 访问的数据，可以选择 DynamoDB 这类高吞吐 KV/宽表存储来承载 <code>Post</code>，重点是帖子写入要容易水平扩展；通过 <code>postId</code> 可以按主键读；通过 <code>creatorId + createdAt</code> 可以按作者回查历史帖子。所以第一步高层架构可以先落成：<code>API Gateway / LB</code>、<code>Post Service</code>、<code>Post Store</code></p><h4 id="二、用户能够关注其他用户" tabindex="-1">二、用户能够关注其他用户 <a class="header-anchor" href="#二、用户能够关注其他用户" aria-label="Permalink to &quot;二、用户能够关注其他用户&quot;">​</a></h4><p>关注本质上是一个多对多关系，直觉上很多人会想到图数据库，但这里并不需要复杂图遍历。因为我们真正需要的只是判断是否关注、查关注列表、查粉丝列表。这种场景下，用一个普通的关系表或 KV 表就足够了，关键不在“图”这个概念，而在于索引方向是否覆盖了查询模式。因此，一个单独的 <code>Follow Service + Follow Store</code> 就足够支撑这部分能力</p><h4 id="三、用户能够查看-feed" tabindex="-1">三、用户能够查看 Feed <a class="header-anchor" href="#三、用户能够查看-feed" aria-label="Permalink to &quot;三、用户能够查看 Feed&quot;">​</a></h4><p>最朴素的办法是这样生成 Feed：先查出当前用户关注了哪些人，再分别查出这些人最近发过的帖子，把这些帖子按时间排序，返回最新的一页。这是一套完全能工作的方案，所以它很适合作为第一版设计。但它有明显问题：当前用户可能关注很多人，每个被关注者都可能发过很多帖子，首页一次请求会扇出大量下游查询，这就是典型的 <code>fan-out on read</code></p><h4 id="四、用户能够分页浏览-feed" tabindex="-1">四、用户能够分页浏览 Feed <a class="header-anchor" href="#四、用户能够分页浏览-feed" aria-label="Permalink to &quot;四、用户能够分页浏览 Feed&quot;">​</a></h4><p>分页本身并不复杂。只要 Feed 按时间倒序排列，那么分页游标就可以直接用时间戳：第一次请求，不带 cursor，返回最新 N 条；后续请求，带上当前页最老帖子的时间戳；服务只返回比它更旧的帖子。相比页码分页，游标分页更适合这种持续写入的动态数据结构，因为它不容易被新帖插入打乱。到这里，我们已经有了一个能工作的基础版系统：<code>Post Service</code> 负责写帖子，<code>Follow Service</code> 负责写关注关系，<code>Feed Service</code> 负责读取关注列表、拉帖子、排序并分页，接下来要做的，就是把它扩到大规模场景</p><h3 id="深入讨论" tabindex="-1">深入讨论 <a class="header-anchor" href="#深入讨论" aria-label="Permalink to &quot;深入讨论&quot;">​</a></h3><h4 id="一、如何处理-我关注了很多人" tabindex="-1">一、如何处理“我关注了很多人” <a class="header-anchor" href="#一、如何处理-我关注了很多人" aria-label="Permalink to &quot;一、如何处理“我关注了很多人”&quot;">​</a></h4><p>这是读路径上的 fan-out 问题。如果一个用户关注了很多人，那么查关注列表本身就会慢，后面还要对每个被关注者再查帖子，最终还要在应用层做大规模排序。这会让一次首页请求衍生成几十、几百，甚至上千次内部查询。更好的思路是把一部分计算提前到写时完成，也就是从 <code>fan-out on read</code> 转向 <code>fan-out on write</code>。具体做法是引入 <code>PrecomputedFeed</code> 表：每个用户维护一份预先算好的 Feed 索引，索引里只保存最近一小段帖子 ID，例如 <code>200</code> 条；读取首页时，直接按 <code>userId</code> 取这份预计算结果。这样首页读取路径就从先查关注、再查很多人的帖子、再合并排序，变成直接按 <code>userId</code> 取一份已经排好序的 Feed 索引，这是对读延迟最直接的优化</p><p>这里有两个很实用的工程结论：预计算 Feed 表里只放轻量引用，例如 <code>postId</code>；只保留最近一小段内容即可，不必追求无限深翻页。假设每个 <code>postId</code> 约 <code>10 bytes</code>，每个用户保留最近 <code>200</code> 条帖子，则单用户大约需要 <code>2KB</code>，如果总用户量是 <code>2B</code>，整体大约 <code>4TB</code>，这在现代分布式存储里是完全可以接受的。同时，这个设计也顺手回答了一个常见追问：如果用户想翻到极深的历史页怎么办？答案是大多数用户不会翻得很深，深翻页可以退化回基础方案，产品层面甚至可以直接不支持极深翻页</p><h4 id="二、如何处理-我有很多粉丝" tabindex="-1">二、如何处理“我有很多粉丝” <a class="header-anchor" href="#二、如何处理-我有很多粉丝" aria-label="Permalink to &quot;二、如何处理“我有很多粉丝”&quot;">​</a></h4><p>当我们引入 <code>PrecomputedFeed</code> 后，读变快了，但写会开始出问题。因为一个用户发帖后，系统需要把这条帖子写进所有粉丝的 <code>PrecomputedFeed</code>，如果这个用户有几百万粉丝，那么一次发帖就会触发几百万次 Feed 写入。最差的做法是让 <code>Post Service</code> 在写完帖子后同步把所有写扩散都做完，这个方案基本不可行：单机连接数扛不住、请求时延扛不住、流量分布会极不均匀，一个明星用户发帖就能拖垮某台实例</p><p>更合理的方案是把这件事异步化：用户发帖；<code>Post Service</code> 先把帖子写入 <code>Post Store</code>；产生一条发帖事件，写入消息队列；后台 <code>Feed Worker</code> 消费事件；Worker 查出发帖者的粉丝列表；把 <code>postId</code> 追加到这些粉丝的 <code>PrecomputedFeed</code>。这样，主链路就从“同步扩散”变成了“异步扩散”，系统能利用我们在非功能需求里预留的那 <code>1</code> 分钟最终一致性窗口</p><p>但异步还不够，因为“大 V”仍然可能带来极端的写放大。所以更进一步的方案是混合模式：普通用户走写扩散，提前写入粉丝 Feed；超级大 V 不做预计算，读取时再动态合并最近帖子。也就是说，系统并不需要所有账号都走同一套策略，对于粉丝极多的账号，可以在 <code>Follow</code> 关系上打一个“这类账号不参与预计算”的标记。最终读取时，<code>Feed Service</code> 同时做两件事：取用户的 <code>PrecomputedFeed</code>；再把这些大 V 的近期帖子动态 merge 进来。这就是经典的 hybrid feed：普通账号偏 <code>fan-out on write</code>，大 V 账号偏 <code>fan-out on read</code>，它的本质不是追求统一，而是承认不同账号类型应该采用不同策略</p><h4 id="三、如何处理热点帖子带来的不均匀读" tabindex="-1">三、如何处理热点帖子带来的不均匀读 <a class="header-anchor" href="#三、如何处理热点帖子带来的不均匀读" aria-label="Permalink to &quot;三、如何处理热点帖子带来的不均匀读&quot;">​</a></h4><p>即使前面已经把 Feed 索引预计算好了，读取时通常还是要再根据 <code>postId</code> 去拿帖子详情。这里又会引出一个新问题：少数热点帖子，尤其是大 V 或爆款内容，在前几个小时可能会被读到非常夸张的次数。如果所有读取都直接打到 <code>Post Store</code>，就会形成 hot key。第一步优化通常是加分布式缓存，例如 Redis：按 <code>postId</code> 缓存帖子详情；帖子很少编辑，因此 TTL 可以比较长；编辑帖子时再主动失效缓存。这样可以把绝大多数读流量挡在缓存层</p><p>但这里还有一个容易被忽略的问题：如果缓存本身是严格按 key 分片的，那么热点 key 还是会把某一个缓存分片打爆。因此，更进一步的方案不是简单的分片缓存，而是冗余缓存：让多个缓存实例都能服务同一个热点帖子；由负载均衡把请求打散到这些实例。这么做的代价是缓存空间利用率下降，冷启动 miss 也会稍多一点，但它能把热点帖子的读流量摊平到多台机器上，换来更稳定的热点吞吐。我们需要意识到存储会有 hot key，缓存自己也会有 hot key，所以缓存层也需要针对热点设计</p><h3 id="整体链路" tabindex="-1">整体链路 <a class="header-anchor" href="#整体链路" aria-label="Permalink to &quot;整体链路&quot;">​</a></h3><h4 id="发帖路径" tabindex="-1">发帖路径 <a class="header-anchor" href="#发帖路径" aria-label="Permalink to &quot;发帖路径&quot;">​</a></h4><ol><li>用户请求 <code>POST /posts</code></li><li><code>Post Service</code> 将帖子写入 <code>Post Store</code></li><li>产生发帖事件，进入队列</li><li><code>Feed Worker</code> 异步消费事件</li><li>对普通账号执行写扩散，更新粉丝的 <code>PrecomputedFeed</code></li><li>对超大 V 账号，跳过预计算，留到读路径合并</li></ol><h4 id="关注路径" tabindex="-1">关注路径 <a class="header-anchor" href="#关注路径" aria-label="Permalink to &quot;关注路径&quot;">​</a></h4><ol><li>用户请求 <code>PUT /users/{id}/follow</code></li><li><code>Follow Service</code> 写入 <code>Follow Store</code></li><li>同步维护正向查询和反向查询所需的索引</li></ol><h4 id="读取-feed-路径" tabindex="-1">读取 Feed 路径 <a class="header-anchor" href="#读取-feed-路径" aria-label="Permalink to &quot;读取 Feed 路径&quot;">​</a></h4><ol><li>用户请求 <code>GET /feed?pageSize={size}&amp;cursor={timestamp}</code></li><li><code>Feed Service</code> 读取自己的 <code>PrecomputedFeed</code></li><li>对被标记为“不预计算”的大 V，拉取最近帖子并动态合并</li><li>根据游标裁剪结果</li><li>批量读取帖子详情，优先命中缓存</li><li>返回最终的 Feed 列表</li></ol><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://www.hellointerview.com/learn/system-design/problem-breakdowns/fb-news-feed" target="_blank" rel="noreferrer">Hello Interview 官方讲解：FB News Feed</a></li></ul>',47)])])}const f=o(r,[["render",t]]);export{p as __pageData,f as default};
